icons.bell='<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>';
function pushKeyBytes(value){const raw=atob(value.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0));}
function showPushSettings(){
 showModal(t('pushTitle'),`<div class="push-settings"><p>${t('pushIntro')}</p><p class="push-install">${t('pushInstall')}</p><p id="push-state" role="status">${t('pushOff')}</p><button class="btn wide" id="push-connect">${t('pushConnect')}</button><div class="push-actions"><button class="btn secondary" id="push-test">${t('pushTest')}</button><button class="btn secondary" id="push-disconnect">${t('pushDisconnect')}</button></div><p class="push-footnote">${t('pushTunnel')}</p></div>`);
 const state=$('#push-state');
 const supported='serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window;
 const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
 const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
 if(!supported||(ios&&!standalone)){state.textContent=t('pushUnsupported');$('#push-connect').disabled=true;$('#push-test').disabled=true;$('#push-disconnect').disabled=true;return;}
 const registration=navigator.serviceWorker.register('/sw.js').then(()=>navigator.serviceWorker.ready);
 if(Notification.permission==='granted')state.textContent=t('pushReady');
 if(Notification.permission==='denied')state.textContent=t('pushBlocked');
 $('#push-connect').onclick=async()=>{
  const button=$('#push-connect');button.disabled=true;let stage='permission';
  try{
   // Ask during the click gesture, before any network request (required on iOS).
   const permission=await Notification.requestPermission();if(permission!=='granted'){state.textContent=t('pushBlocked');return;}
   stage='service-worker';const reg=await registration;stage='server-key';const key=await api('/push/key');
   let subscription=await reg.pushManager.getSubscription();
   if(subscription&&subscription.options.applicationServerKey){const local=Array.from(new Uint8Array(subscription.options.applicationServerKey)).join(',');if(local!==Array.from(pushKeyBytes(key.publicKey)).join(',')){await subscription.unsubscribe();subscription=null;}}
   stage='push-subscription';subscription=subscription||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:pushKeyBytes(key.publicKey)});
   stage='save-subscription';
   await api('/push/subscribe',{method:'POST',body:{subscription:subscription.toJSON(),language:lang}});state.textContent=t('pushEnabled');
  }catch(error){state.textContent=error.status?error.message:`${t('pushNetwork')} (${stage}: ${error.name||'Error'} — ${String(error.message||'').slice(0,160)})`;}finally{button.disabled=false;}
 };
 $('#push-disconnect').onclick=async()=>{try{const reg=await registration,sub=await reg.pushManager.getSubscription();if(sub){await api('/push/unsubscribe',{method:'POST',body:{endpoint:sub.endpoint}});await sub.unsubscribe();}state.textContent=t('pushDisabled');}catch{state.textContent=t('pushNetwork');}};
 $('#push-test').onclick=async()=>{const button=$('#push-test');button.disabled=true;try{const result=await api('/push/test',{method:'POST',body:{}});state.textContent=t(result.accepted?'pushTestSent':result.devices?'pushNetwork':'pushNoDevice');if(!result.accepted&&result.errors?.length)state.textContent+=` (${result.errors[0].status}: ${result.errors[0].reason})`;}catch(error){state.textContent=error.message||t('pushNetwork');}finally{button.disabled=false;}};
}
function banner(){return `<div class="banner">${icon('info')}<span>${t('demoBanner')}</span></div>`;}
function stat(label,value,sub,ic='chart',attention=false){return `<div class="stat panel"><div class="stat-label">${t(label)}${icon(ic)}</div><div class="stat-value ${attention?'attention':''}">${value}</div><div class="stat-sub">${e(sub)}</div></div>`;}
function arrangeWorkspace(role){
 const main=$('.main');
 main.classList.add(`${role}-workspace`);
 const intro=$('.page-intro',main);
 const eyebrow=$('.eyebrow',intro);
 if(eyebrow)eyebrow.textContent=fmt(new Date(),{weekday:'long',day:'numeric',month:'long'});
 if(role==='doctor'){
  const stats=$('.stats',main),registry=$('#patient-list').closest('section');
  const layout=document.createElement('div');layout.className='clinic-layout';
  registry.before(layout);layout.append(registry,stats);
  const heading=document.createElement('h2');heading.className='section-caption';heading.textContent=t('clinicToday');stats.prepend(heading);
 }else{
  $('h1',intro).textContent=t('healthTitle');
  const stats=$('.stats',main),welcome=$('.welcome-strip',main),split=$('.split',main);
  const latest=stats.firstElementChild;
  const hero=document.createElement('div');hero.className='health-overview';welcome.before(hero);hero.append(latest,welcome);
  latest.classList.add('reading-feature');
  const unit=document.createElement('div');unit.className='reading-unit';unit.textContent=t('unit');$('.stat-value',latest).after(unit);
  const trend=split.firstElementChild,feedback=split.lastElementChild;
  const timeline=document.createElement('div');timeline.className='health-timeline';split.before(timeline);timeline.append(trend,stats);split.replaceWith(feedback);
  feedback.classList.add('care-feedback');
  const historySection=$('.table-wrap',main)?.closest('section')||main.querySelector('section:last-of-type');
  trend.id='health-trend';feedback.id='care-feedback';if(historySection)historySection.id='health-history';
  const nav=$('.nav-list');
  nav.insertAdjacentHTML('beforeend',`<button class="nav-item" data-section="health-history">${icon('clock')}${t('history')}</button><button class="nav-item" data-section="care-feedback">${icon('users')}${t('doctorFeedback')}</button>`);
  $$('[data-section]').forEach(button=>button.onclick=()=>{document.getElementById(button.dataset.section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});$$('.nav-item').forEach(item=>item.classList.toggle('active',item===button));});
 }
}
