 $('#patient-list').innerHTML=list.length?`<div class="table-wrap"><table class="patient-table"><thead><tr><th>${t('patientCol')}</th><th>${t('latest')}</th><th>${t('status')}</th><th>${t('updated')}</th><th>${t('action')}</th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="row"><div class="avatar">${e(p.patient.code.slice(-2))}</div><div><div class="patient-name">${e(p.patient.name)}</div><div class="patient-code">${e(p.patient.code)} &nbsp; ${p.patient.synthetic?t('synthetic'):t('participant')}</div></div></div></td><td>${p.latest?`<div class="bp">${p.latest.systolic}<span> / </span>${p.latest.diastolic}</div><div class="patient-code">${p.latest.pulse} ${t('bpm')}</div>`:`<span class="muted">${t('noReadings')}</span>`}</td><td><div class="badges">${flags(p)}</div><div class="small muted" style="margin-top:7px">${t(p.needsReview?'new':'reviewed')}</div></td><td class="small muted nowrap">${fmt(p.latest?.measured_at)}</td><td><button class="btn secondary compact" data-patient="${p.patient.id}">${t('open')}${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('search')}<h3>${t('noResults')}</h3><p>${t('noResultsSub')}</p></div>`;
 if(list.length)$('#patient-list').innerHTML=`<div class="patient-inbox">${list.map(p=>`<button class="patient-item" data-patient="${p.patient.id}"><span class="avatar">${e(p.patient.name.slice(0,1))}</span><span class="patient-identity"><strong>${e(p.patient.name)}</strong><span>${e(p.patient.code)} · ${t(p.needsReview?'new':'reviewed')}</span></span><span class="patient-reading">${p.latest?`<strong>${p.latest.systolic}<span> / </span>${p.latest.diastolic}</strong><small>${fmt(p.latest.measured_at)}</small>`:`<small>${t('noReadings')}</small>`}</span><span class="inbox-flags">${flags(p)}</span><span class="inbox-chevron">${icon('arrow')}</span></button>`).join('')}</div>`;
 $$('[data-patient]').forEach(b=>b.onclick=()=>openPatient(Number(b.dataset.patient)));
