async function openPatient(id){try{detail=await api(`/patients/${id}`);view='detail';renderDetail();window.scrollTo(0,0);}catch(err){toast(err.message,true);}}
function chart(d){
 const readings=d.readings.filter(r=>Date.parse(r.measured_at)>=Date.now()-14*86400000).slice().reverse();
 if(!readings.length)return `<div class="empty">${icon('chart')}<p>${t('emptyChart')}</p></div>`;
 const W=700,H=245,pad={l:44,r:20,t:20,b:35};
 const minX=Date.now()-14*86400000,maxX=Date.now();
 const vals=readings.flatMap(r=>[r.systolic,r.diastolic]);
 const minY=Math.floor((Math.min(...vals)-10)/20)*20,maxY=Math.ceil((Math.max(...vals)+10)/20)*20;
 const x=r=>pad.l+(Date.parse(r.measured_at)-minX)/(maxX-minX)*(W-pad.l-pad.r);
 const y=v=>pad.t+(maxY-v)/(maxY-minY)*(H-pad.t-pad.b);
 const ticks=[];for(let v=minY;v<=maxY;v+=20)ticks.push(v);
 const line=field=>readings.map(r=>`${x(r).toFixed(1)},${y(r[field]).toFixed(1)}`).join(' ');
 return `<div class="chart-legend"><span><i class="line"></i>${t('systolic')}</span><span><i class="line orange"></i>${t('diastolic')}</span></div><div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${t('trend')}, ${readings.length} ${t('measurements')}">${ticks.map(v=>`<line x1="${pad.l}" x2="${W-pad.r}" y1="${y(v)}" y2="${y(v)}" stroke="#e9efea" stroke-dasharray="3 4"/><text x="${pad.l-10}" y="${y(v)+3}" text-anchor="end" fill="#8a9b97" font-size="10">${v}</text>`).join('')}${[0,4,8,12].map(day=>{const date=new Date(minX+day*86400000);const xp=pad.l+day/14*(W-pad.l-pad.r);return `<text x="${xp}" y="${H-9}" text-anchor="middle" fill="#8a9b97" font-size="10">${e(dateOnly(date))}</text>`;}).join('')}<polyline points="${line('systolic')}" fill="none" stroke="#168c80" stroke-width="2.3"/><polyline points="${line('diastolic')}" fill="none" stroke="#cf9968" stroke-width="2"/>${readings.map(r=>`<circle cx="${x(r)}" cy="${y(r.systolic)}" r="3.4" fill="#168c80"><title>${e(fmt(r.measured_at))}: ${r.systolic}/${r.diastolic} ${t('unit')}</title></circle><circle cx="${x(r)}" cy="${y(r.diastolic)}" r="2.7" fill="#cf9968"/>`).join('')}</svg></div><p class="chart-detail">${t('chartNote')}</p>`;
}
function history(d){return `<section class="panel"><div class="toolbar"><div><h2>${t('history')}</h2><p class="small">${t('historySub')}</p></div><a class="btn secondary compact" href="/api/patients/${d.patient.id}/export" download>${icon('download')}${t('export')}</a></div>${d.readings.length?`<div class="table-wrap"><table><thead><tr><th>${t('dateTime')}</th><th>${t('pressure')} · ${t('unit')}</th><th>${t('pulse')} · ${t('bpm')}</th><th>${t('note')}</th><th>${t('source')}</th></tr></thead><tbody>${d.readings.map(r=>`<tr><td class="nowrap">${fmt(r.measured_at)}</td><td><strong>${r.systolic} / ${r.diastolic}</strong></td><td>${r.pulse}</td><td class="note-cell">${e(r.note)||'—'}</td><td>${pill(t(r.source==='demo'?'demoSource':'manual'),r.source==='demo'?'neutral':'teal')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${t('noReadingHistory')}</div>`}</section>`;}
function reviewHistory(d){return d.reviews.length?d.reviews.map(r=>`<div class="review-history"><div class="row between"><strong class="small">${e(r.doctor_name)}</strong><span class="small muted">${fmt(r.reviewed_at)}</span></div><p>${e(r.comment)||t('noComment')}</p></div>`).join(''):`<p class="muted small" style="margin-top:15px">${t('noReviews')}</p>`;}
function renderDetail(){
 const d=detail;
 shell(`<button class="back" id="back">${icon('back')}${t('back')}</button><div class="page-intro"><div class="patient-banner" style="margin:0"><div class="avatar">${e(d.patient.code.slice(-2))}</div><div><h1>${e(d.patient.name)}</h1><p>${e(d.patient.code)} &nbsp; ${badge(d)}</p></div></div><button class="btn secondary compact" id="refresh-patient">${icon('refresh')}${t('refresh')}</button></div><div class="badges" style="margin-bottom:20px">${flags(d)}${pill(t(d.needsReview?'new':'reviewed'),d.needsReview?'orange':'teal')}</div><section class="stats">${stat('lastReading',d.latest?`${d.latest.systolic}<span class="small muted"> / </span>${d.latest.diastolic}`:'—',d.latest?fmt(d.latest.measured_at):t('noReadings'),'pulse')}${stat('average',d.average?`${d.average.systolic}<span class="small muted"> / </span>${d.average.diastolic}`:'—',t('unit'))}${stat('measurements',d.count14,`${d.days14} ${t('days')}`,'calendar')}${stat('lastReview',d.reviews.length?dateOnly(d.reviews[0].reviewed_at):'—',d.reviews.length?fmt(d.reviews[0].reviewed_at,{hour:'2-digit',minute:'2-digit'}):t('notReviewed'),'check')}</section><div class="split"><section class="panel"><div class="chart-header"><div><h2>${t('trend')}</h2><p>${t('twoWeeks')} · ${t('unit')}</p></div>${pill(t('overview'),'teal')}</div>${chart(d)}</section><section class="panel review-box"><h2>${t('reviewTitle')}</h2><p>${t('reviewSub')}</p><form id="review-form"><div class="field"><label for="review-comment">${t('comment')}</label><textarea id="review-comment" maxlength="1000" placeholder="${t('commentPlaceholder')}"></textarea></div><button class="btn wide">${icon('check')}${t('reviewButton')}</button></form><div class="review-meta">${t('registryFoot')}</div></section></div>${history(d)}<section class="panel panel-pad section-gap"><h2>${t('reviewHistory')}</h2>${reviewHistory(d)}</section>`);
 $('#back').onclick=()=>{view='dashboard';renderDoctor();};
 $('.main').classList.add('clinic-detail');
 $('.patient-banner .avatar').textContent=d.patient.name.slice(0,1);
 $('.stats').outerHTML=MetricStrip(d);
 $('.split').firstElementChild.outerHTML=PressureChart(d);
 $('.split').classList.add('clinic-review-grid');
 bindPressureChart(d);
 $('#refresh-patient').onclick=()=>openPatient(d.patient.id);
 mountAssistant(d,$('.page-intro'));
 $('#review-form').onsubmit=async ev=>{ev.preventDefault();const btn=$('button',ev.target);btn.disabled=true;try{await api(`/patients/${d.patient.id}/review`,{method:'POST',body:{comment:$('#review-comment').value,last_reading_id:maxReadingId(d)}});data=await api('/dashboard');detail=await api(`/patients/${d.patient.id}`);renderDetail();toast(t('reviewSaved'));}catch(err){toast(err.status===409?t('reviewConflict'):err.message,true);btn.disabled=false;}};
}
// Patient workspace components. API payloads and persistence stay in the existing flow.
