function showAssistant(d){
 showModal(t('assistant'),`<div class="assistant-body"><p class="assistant-mode">${t('assistantMode')}</p><p class="assistant-intro">${t('assistantIntro')}</p><div class="assistant-topics" role="group" aria-label="${t('assistant')}">${[['latest','assistantLatest'],['summary','assistantSummary'],['technique','assistantTechnique'],['doctor','assistantDoctor']].map(([id,key])=>`<button class="btn secondary compact" data-assistant-topic="${id}" aria-pressed="false">${t(key)}</button>`).join('')}</div><label class="assistant-special"><input type="checkbox" id="assistant-special">${t('assistantSpecial')}</label><div id="assistant-result" aria-live="polite" aria-busy="false"></div><div class="assistant-emergency"><button class="btn secondary" id="assistant-symptoms">${t('assistantSymptoms')}</button><p>${t('assistantSymptomsHelp')}</p><a href="tel:103">103</a> · <a href="tel:112">112</a></div></div>`);
 modal.classList.add('reading-drawer');modal.dataset.theme=healthTheme;
 let sequence=0,topic='latest',warningSymptoms=false;
 async function ask(next=topic){
  topic=next;const run=++sequence,result=$('#assistant-result');result.setAttribute('aria-busy','true');result.innerHTML=`<p class="assistant-loading">${t('assistantLoading')}</p>`;
  $$('[data-assistant-topic]',modal).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.assistantTopic===topic)));
  try{
   const r=await api('/assistant',{method:'POST',body:{topic,language:lang,warningSymptoms,specialPopulation:$('#assistant-special').checked,...(user.role==='doctor'?{patientId:d.patient.id}:{})}});
   if(run!==sequence||!modal.open)return;
   const s=r.snapshot,l=s.latest;
   result.innerHTML=`<div class="assistant-evidence"><small>${t('assistantBasis')}</small><strong>${l?`${l.systolic}/${l.diastolic} ${t('unit')} · ${l.pulse} ${t('bpm')}`:t('assistantEmpty')}</strong>${l?`<time>${fmt(l.measured_at)}</time>`:''}<p>${t('assistantAverage')}: ${s.average?`${s.average.systolic}/${s.average.diastolic}`:'—'} · ${s.count14} ${t('assistantRecords')}</p></div><div class="assistant-answer ${r.urgency==='emergency'||r.urgency==='urgent'?'assistant-urgent':''}" ${r.urgency==='emergency'?'role="alert"':''}>${r.sections.map(p=>`<p>${e(p)}</p>`).join('')}</div><p class="assistant-boundary">${e(r.boundary)}</p><details class="assistant-sources"><summary>${t('assistantSources')}</summary>${r.sources.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)}</a>`).join('')}</details>`;
  }catch{if(run===sequence)result.innerHTML=`<p class="assistant-answer assistant-urgent" role="alert">${t('assistantFailure')}</p>`;}
  finally{if(run===sequence)result.setAttribute('aria-busy','false');}
 }
 $$('[data-assistant-topic]',modal).forEach(b=>b.onclick=()=>ask(b.dataset.assistantTopic));
 $('#assistant-special').onchange=()=>ask();
 $('#assistant-symptoms').onclick=()=>{warningSymptoms=true;++sequence;const result=$('#assistant-result');result.setAttribute('aria-busy','false');result.innerHTML=`<div class="assistant-answer assistant-urgent" role="alert"><p>${t('assistantEmergency')}</p><a href="tel:103">103</a> · <a href="tel:112">112</a></div>`;};
 ask();
}
function localInputDate(){const d=new Date();return new Date(d-Date.now()%60000-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function showReading(){
 showModal(t('addReading'),`<p class="metric-note" style="margin-top:0">${t('readingSub')}</p><form id="reading-form"><div class="field-row three"><div class="field"><label for="systolic">${t('systolic')}</label><input id="systolic" name="systolic" type="number" min="60" max="260" step="1" inputmode="numeric" placeholder="120" required><small>${t('unit')} · 60–260</small></div><div class="field"><label for="diastolic">${t('diastolic')}</label><input id="diastolic" name="diastolic" type="number" min="30" max="180" step="1" inputmode="numeric" placeholder="80" required><small>${t('unit')} · 30–180</small></div><div class="field"><label for="pulse">${t('pulse')}</label><input id="pulse" name="pulse" type="number" min="30" max="220" step="1" inputmode="numeric" placeholder="72" required><small>${t('bpm')} · 30–220</small></div></div><div class="field"><label for="measured-at">${t('measuredAt')}</label><input id="measured-at" name="measured_at" type="datetime-local" value="${localInputDate()}" max="${localInputDate()}" required></div><div class="field"><label for="reading-note">${t('note')}</label><textarea id="reading-note" name="note" maxlength="500" placeholder="${t('notePlaceholder')}"></textarea></div><p class="form-error" id="reading-error" role="alert"></p><div class="modal-footer"><button class="btn secondary" type="button" id="cancel-modal">${t('cancel')}</button><button class="btn" type="submit">${icon('check')}${t('save')}</button></div></form>`);
 $('#cancel-modal').onclick=()=>modal.close();
 $('#reading-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target);const b={systolic:Number(f.get('systolic')),diastolic:Number(f.get('diastolic')),pulse:Number(f.get('pulse')),measured_at:new Date(f.get('measured_at')).toISOString(),note:f.get('note')};
  if(b.systolic<=b.diastolic){$('#reading-error').textContent=t('invalidPressure');return;}
  const btn=$('button[type=submit]',ev.target);btn.disabled=true;
  try{await api('/readings',{method:'POST',body:b});modal.close();await load();toast(t('readingSaved'));}catch(err){$('#reading-error').textContent=err.message;btn.disabled=false;}
 };
}
function showEnroll(){
 showModal(t('enrollTitle'),`<p class="metric-note" style="margin-top:0">${t('enrollSub')}</p><form id="enroll-form"><div class="field"><label for="patient-name">${t('name')}</label><input id="patient-name" name="name" minlength="2" maxlength="80" placeholder="${t('namePlaceholder')}" required></div><div class="field"><label for="patient-email">${t('email')}</label><input id="patient-email" name="email" type="email" maxlength="120" placeholder="participant05@example.test" required></div><div class="field"><label for="patient-password">${t('password')}</label><input id="patient-password" name="password" type="password" minlength="10" maxlength="128" autocomplete="new-password" required><small>${t('passwordHelp')}</small></div><label class="check"><input id="patient-consent" name="consent" type="checkbox" required><span>${t('consent')}</span></label><p class="consent-note">${t('consentDetails')}</p><p class="form-error" id="enroll-error" role="alert"></p><div class="modal-footer"><button class="btn secondary" type="button" id="cancel-modal">${t('cancel')}</button><button class="btn">${icon('plus')}${t('create')}</button></div></form>`);
 $('#cancel-modal').onclick=()=>modal.close();
 $('#enroll-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target);const btn=$('button:not([type=button])',ev.target);btn.disabled=true;try{await api('/patients',{method:'POST',body:{name:f.get('name'),email:f.get('email'),password:f.get('password'),consent:f.get('consent')==='on'}});modal.close();filter='all';search='';await load();toast(t('created'));}catch(err){$('#enroll-error').textContent=err.message;btn.disabled=false;}};
}
function renderSettings(){
 const rules=data.rules;
 shell(`<div class="page-intro"><div><div class="eyebrow">MedSense</div><h1 style="margin-top:8px">${t('settingsTitle')}</h1><p>${t('settingsSub')}</p></div></div><div class="banner warning">${icon('info')}<span>${t('settingsWarning')}</span></div><div class="settings-grid"><section class="panel"><form id="settings-form"><h2>${t('repeatedRule')}</h2><p class="metric-note">${t('repeatedHelp')}</p><div class="field-row"><div class="field"><label for="rule-systolic">${t('systolic')}</label><input id="rule-systolic" name="systolic" type="number" value="${rules.systolic}" min="120" max="220" step="1" required><small>${t('unit')}</small></div><div class="field"><label for="rule-diastolic">${t('diastolic')}</label><input id="rule-diastolic" name="diastolic" type="number" value="${rules.diastolic}" min="70" max="140" step="1" required><small>${t('unit')}</small></div></div><hr class="divider"><div class="field"><label for="missed-hours">${t('missingRule')}</label><input id="missed-hours" name="missed_hours" type="number" value="${rules.missed_hours}" min="12" max="168" step="1" required><small>${t('missingHelp')}</small></div><button class="btn">${t('saveRules')}</button></form></section><section class="panel setting-explain"><h2>${t('logicTitle')}</h2><p>${t('logicText')}</p><p>${t('logicText2')}</p><div class="rule-equation">${t('repeatedRule')}: 2 × / 72h<br>${t('missingRule')}: ${rules.missed_hours}h</div></section></div>`);
 $('#settings-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),btn=$('button',ev.target);btn.disabled=true;try{await api('/settings',{method:'PUT',body:Object.fromEntries([...f].map(([k,v])=>[k,Number(v)]))});await load();toast(t('rulesSaved'));}catch(err){toast(err.message,true);btn.disabled=false;}};
}
function renderMetrics(){
 const count=k=>metrics.counts.find(v=>v.event===k)?.count||0;
 shell(`<div class="page-intro"><div><div class="eyebrow">CUSTOMER DEVELOPMENT</div><h1 style="margin-top:8px">${t('metricsTitle')}</h1><p>${t('metricsSub')}</p></div><button id="export-metrics" class="btn secondary">${icon('download')}${t('metricsExport')}</button></div><section class="stats">${stat('participants',metrics.participants,t('metricReal'),'users')}${stat('activePatients',metrics.activePatients,t('metricActive'),'pulse')}${stat('readingsAdded',count('reading_added'),t('metricManual'),'chart')}${stat('reviewsDone',count('review_completed'),t('metricReviews'),'check')}</section><p class="metric-note">${t('metricsNote')}</p><section class="panel"><div class="toolbar"><h2>${t('events')}</h2><button class="btn secondary compact" id="refresh-metrics">${icon('refresh')}${t('refresh')}</button></div>${metrics.events.length?`<div class="table-wrap"><table><thead><tr><th>${t('dateTime')}</th><th>${t('account')}</th><th>${t('event')}</th><th>${t('source')}</th></tr></thead><tbody>${metrics.events.map(ev=>`<tr><td>${fmt(ev.created_at)}</td><td>${e(ev.code)}</td><td>${e(t(ev.event))}</td><td>${pill(t(ev.synthetic?'synthetic':'participant'),ev.synthetic?'neutral':'teal')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${t('noEvents')}</div>`}</section>`);
 $('#refresh-metrics').onclick=()=>load().catch(err=>toast(err.message,true));
 $('#export-metrics').onclick=()=>{const rows=[['account','event','timestamp_utc','synthetic'],...metrics.events.map(ev=>[ev.code,ev.event,ev.created_at,ev.synthetic])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MedSense-MVP-events.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
function render(){document.documentElement.lang=lang;document.title='MedSense · '+t('title');if(!user)return renderLogin();if(view==='detail')return renderDetail();if(view==='metrics')return renderMetrics();if(view==='settings')return renderSettings();if(user.role==='doctor')renderDoctor();else renderPatient();}
async function load(){
 if(user?.role==='patient'&&!data){
  shell(`<div class="health-page" aria-busy="true" aria-label="${t('loading')}"><header class="health-header"><h1>${t('healthTitle')}</h1></header><div class="clinical-grid health-loading"><section class="clinical-panel pressure-panel"></section><aside class="health-rail"><section class="clinical-panel"></section></aside></div></div>`);
  $('.shell').classList.add('clinical-shell');$('.shell').dataset.theme=healthTheme;$('.main').classList.add('clinical-main');
 }
 data=await api('/dashboard');if(view==='metrics')metrics=await api('/metrics');render();
}
async function init(){try{
 config=await api('/config');
 if(config.publicMode){
  Object.assign(words.kk,kazakhRemote);
  Object.assign(words.ru,{local:'Удалённый Beta-тест',localHelp:'Учебное тестирование интерфейса. Используйте вымышленные показатели. Введите индивидуальные данные для входа, полученные от команды MedSense.',participants:'Кабинетов участников',metricReal:'Подготовленные учётные записи',enrollSub:'Используйте псевдоним и тестовую почту. Передайте данные для входа участнику лично. Для этого Beta-теста вводите только вымышленные показатели.'});
  Object.assign(words.en,{local:'Remote beta test',localHelp:'Educational interface testing. Use fictional readings. Enter the individual credentials provided by the MedSense team.',participants:'Participant accounts',metricReal:'Prepared user accounts',enrollSub:'Use a pseudonym and a test email. Share credentials personally. Enter fictional readings only for this beta test.'});
 }
 user=await api('/me');await load();
 const requestedPatient=Number(new URL(location.href).searchParams.get('patient'));
 if(user.role==='doctor'&&requestedPatient>0&&Number.isSafeInteger(requestedPatient))await openPatient(requestedPatient);
 }catch(err){
 if(user?.role==='patient'&&err.status!==401){
  shell(`<div class="health-page"><header class="health-header"><h1>${t('healthTitle')}</h1></header><div class="health-error" role="alert">${t('error')} <button id="retry-health">${t('retry')}</button></div></div>`);
  $('.shell').classList.add('clinical-shell');$('.shell').dataset.theme=healthTheme;$('.main').classList.add('clinical-main');$('#retry-health').onclick=()=>init();
 }else{if(err.status!==401)toast(t('error'),true);renderLogin();}
}}
init();
